 "roleplay": {"title":"ROLEPLAY — Role · Objective · Limits · Example · Persona · Language · Audience · Yield","label":"ROLEPLAY","fields":[{"id":"forge_roleplay_0","label":"Role","icon":"person","hint":"Who the AI should play","rows":2,"weight":1.5,"placeholder":"e.g. You are a hiring manager at a mid sized fintech company..."},{"id":"forge_roleplay_1","label":"Objective","icon":"target","hint":"What the roleplay should achieve","rows":4,"weight":3,"placeholder":"e.g. Run a realistic mock interview for a product manager role and give feedback after...","required":true},{"id":"forge_roleplay_2","label":"Limits","icon":"rule","hint":"Boundaries the AI must keep","rows":2,"weight":1,"placeholder":"e.g. Ask one question at a time, stay in character until I type END..."},{"id":"forge_roleplay_3","label":"Example","icon":"star","hint":"A sample exchange or question","rows":2,"weight":1,"placeholder":"e.g. Tell me about a time you had to say no to a senior stakeholder..."},{"id":"forge_roleplay_4","label":"Persona","icon":"record_voice_over","hint":"Personality and manner to adopt","rows":2,"weight":1,"placeholder":"e.g. Direct, slightly sceptical, warms up when answers are specific..."},{"id":"forge_roleplay_5","label":"Language","icon":"chat","hint":"Style and vocabulary to use","rows":2,"weight":1,"placeholder":"e.g. Professional UK English, avoid jargon unless I use it first..."},{"id":"forge_roleplay_6","label":"Audience","icon":"groups","hint":"Who is taking part","rows":2,"weight":1,"placeholder":"e.g. A mid career candidate moving from marketing into product..."},{"id":"forge_roleplay_7","label":"Yield","icon":"check_circle","hint":"What to deliver at the end","rows":2,"weight":1,"placeholder":"e.g. A score out of 10 per answer and three specific improvement tips..."}]},
 "cot": {"title":"CoT — Chain of Thought","label":"CoT","fields":[{"id":"forge_cot_0","label":"Task","icon":"task_alt","hint":"The problem to reason through","rows":4,"weight":3,"placeholder":"e.g. Work out whether we should hire a contractor or a permanent developer for this project...","required":true},{"id":"forge_cot_1","label":"Context","icon":"info","hint":"Facts and figures the AI needs","rows":3,"weight":1.5,"placeholder":"e.g. Budget is £60k, project lasts eight months, we may need ongoing maintenance..."},{"id":"forge_cot_2","label":"Reasoning steps","icon":"psychology","hint":"How to think it through","rows":2,"weight":1,"placeholder":"e.g. Think step by step, compare costs, risks and flexibility before concluding..."},{"id":"forge_cot_3","label":"Output format","icon":"description","hint":"How to present the answer","rows":2,"weight":1,"placeholder":"e.g. Show your reasoning as numbered steps, then a one sentence recommendation..."}]},
 "cot2": {"title":"CoT-SC — Chain of Thought · Self-Consistency","label":"CoT-SC","fields":[{"id":"forge_cot2_0","label":"Task","icon":"task_alt","hint":"The problem to solve","rows":4,"weight":3,"placeholder":"e.g. Estimate how many coffee shops a town of 50,000 people can support...","required":true},{"id":"forge_cot2_1","label":"Context","icon":"info","hint":"Facts and assumptions to use","rows":3,"weight":1.5,"placeholder":"e.g. Average spend is £3.50, about 30% of adults buy coffee out daily..."},{"id":"forge_cot2_2","label":"Reasoning paths","icon":"account_tree","hint":"How many independent attempts to make","rows":2,"weight":1,"placeholder":"e.g. Solve it three separate ways using different assumptions each time..."},{"id":"forge_cot2_3","label":"Consistency check","icon":"compare_arrows","hint":"How to pick the final answer","rows":2,"weight":1,"placeholder":"e.g. Compare the three answers and give the one most paths agree on, with a confidence level..."}]},
