 "got": {"title":"GoT — Graph of Thought","label":"GoT","fields":[{"id":"forge_got_0","label":"Problem","icon":"task_alt","hint":"The question to reason about","rows":4,"weight":3,"placeholder":"e.g. Design a content strategy that serves both our SEO goals and our newsletter growth...","required":true},{"id":"forge_got_1","label":"Thought nodes","icon":"lightbulb","hint":"Key ideas or subproblems to explore","rows":3,"weight":1.5,"placeholder":"e.g. Keyword gaps, audience pain points, repurposing options, posting cadence..."},{"id":"forge_got_2","label":"Connections","icon":"account_tree","hint":"How ideas should link or merge","rows":2,"weight":1,"placeholder":"e.g. Combine overlapping ideas, note where one idea feeds another..."},{"id":"forge_got_3","label":"Synthesis","icon":"check_circle","hint":"How to bring it together","rows":2,"weight":1,"placeholder":"e.g. Merge the strongest connected ideas into one plan with three priorities..."}]},
