 "react": {"title":"ReAct — Reason · Act","label":"REACT","fields":[{"id":"forgeReRole","label":"Role","icon":"person","hint":"Who the AI is acting as","rows":2,"required":true,"weight":1.5,"placeholder":"e.g. You are a troubleshooting assistant for a SaaS product..."},{"id":"forgeReExamples","label":"Examples","icon":"library_books","hint":"Sample reasoning traces or outputs","rows":3,"weight":1,"placeholder":"e.g. Thought: check logs first. Action: search error code..."},{"id":"forgeReAction","label":"Action","icon":"play_arrow","hint":"What action to take at each step","rows":3,"required":true,"weight":2,"placeholder":"e.g. Diagnose the root cause and propose a fix, showing your reasoning..."},{"id":"forgeReContext","label":"Context","icon":"info","hint":"Available tools or information","rows":3,"weight":1.5,"placeholder":"e.g. You have access to: error logs, the changelog, and the user report..."},{"id":"forgeReTask","label":"Task","icon":"task_alt","hint":"The overall objective","rows":2,"required":true,"weight":2,"placeholder":"e.g. Resolve the reported bug and explain the fix in plain language..."}]},
