 "debate": {"title":"DEBATE — Position · Counter · Rebut · Resolve","label":"DEBATE","fields":[{"id":"forge_debate_0","label":"Position","icon":"campaign","hint":"The topic and opening stance","rows":4,"weight":3,"placeholder":"e.g. Argue that our company should adopt a four day working week...","required":true},{"id":"forge_debate_1","label":"Counter","icon":"compare_arrows","hint":"The opposing argument to raise","rows":2,"weight":1.5,"placeholder":"e.g. Present the strongest case against, focusing on client coverage and costs..."},{"id":"forge_debate_2","label":"Rebut","icon":"chat","hint":"How each side should respond","rows":2,"weight":1,"placeholder":"e.g. Each side answers the other's two strongest points directly..."},{"id":"forge_debate_3","label":"Resolve","icon":"check_circle","hint":"How to conclude the debate","rows":2,"weight":1,"placeholder":"e.g. Give a balanced verdict and a recommended pilot plan for three months..."}]},
