 "firstprinc": {"title":"FIRST-PRINCIPLES — Assumptions · Truths · Rebuild · Validate","label":"FIRST-PRINCIPLES","fields":[{"id":"forge_firstprinc_0","label":"Assumptions","icon":"help","hint":"The problem and its assumptions","rows":4,"weight":3,"placeholder":"e.g. Why do we assume a new marketing website must cost £30k and take six months?...","required":true},{"id":"forge_firstprinc_1","label":"Truths","icon":"check_circle","hint":"Basic facts you know are true","rows":3,"weight":1.5,"placeholder":"e.g. We need ten pages, a contact form and fast load times. Content already exists..."},{"id":"forge_firstprinc_2","label":"Rebuild","icon":"extension","hint":"How to build from those truths","rows":2,"weight":1,"placeholder":"e.g. Design the cheapest, fastest approach using only those essentials..."},{"id":"forge_firstprinc_3","label":"Validate","icon":"rule","hint":"How to test the new approach","rows":2,"weight":1,"placeholder":"e.g. Check it against our goals and list any risks we have ignored..."}]},
 "scamper": {"title":"SCAMPER — Substitute · Combine · Adapt · Modify · Put · Eliminate · Reverse","label":"SCAMPER","fields":[{"id":"forge_scamper_0","label":"Substitute","icon":"compare_arrows","hint":"What could be swapped out","rows":4,"weight":3,"placeholder":"e.g. Our reusable water bottle. Could we substitute the plastic lid for bamboo?...","required":true},{"id":"forge_scamper_1","label":"Combine","icon":"extension","hint":"What could be merged together","rows":2,"weight":1,"placeholder":"e.g. Combine the bottle with a built in fruit infuser..."},{"id":"forge_scamper_2","label":"Adapt","icon":"tune","hint":"What could be borrowed from elsewhere","rows":2,"weight":1,"placeholder":"e.g. Adapt the subscription model used by razor brands for replacement lids..."},{"id":"forge_scamper_3","label":"Modify","icon":"edit","hint":"What could be changed or resized","rows":2,"weight":1,"placeholder":"e.g. Offer a smaller 350ml version for children's lunchboxes..."},{"id":"forge_scamper_4","label":"Put","icon":"lightbulb","hint":"Other uses for it","rows":2,"weight":1,"placeholder":"e.g. Market it as a plant watering bottle for indoor gardeners..."},{"id":"forge_scamper_5","label":"Eliminate","icon":"filter_alt","hint":"What could be removed","rows":2,"weight":1,"placeholder":"e.g. Remove the carry strap to cut cost and packaging..."},{"id":"forge_scamper_6","label":"Reverse","icon":"compare_arrows","hint":"What could be flipped or reordered","rows":2,"weight":1,"placeholder":"e.g. Let customers design the bottle first, then we manufacture it..."}]},
 "sixhats": {"title":"SIX-HATS — Facts · Feelings · Caution · Benefits · Creativity · Process","label":"SIX-HATS","fields":[{"id":"forge_sixhats_0","label":"Facts","icon":"info","hint":"Known data about the decision","rows":4,"weight":3,"placeholder":"e.g. We are deciding whether to open a second shop. Current sales are £400k a year...","required":true},{"id":"forge_sixhats_1","label":"Feelings","icon":"chat","hint":"Gut reactions and emotions","rows":2,"weight":1,"placeholder":"e.g. The team is excited but worried about being stretched thin..."},{"id":"forge_sixhats_2","label":"Caution","icon":"warning","hint":"Risks and possible problems","rows":2,"weight":1,"placeholder":"e.g. Rent is high, staff hiring is slow, and the high street is declining..."},{"id":"forge_sixhats_3","label":"Benefits","icon":"trending_up","hint":"Upsides and opportunities","rows":2,"weight":1,"placeholder":"e.g. Wider reach, bulk buying discounts and a stronger local brand..."},{"id":"forge_sixhats_4","label":"Creativity","icon":"lightbulb","hint":"New ideas and alternatives","rows":2,"weight":1,"placeholder":"e.g. Try a pop up shop for three months before signing a lease..."},{"id":"forge_sixhats_5","label":"Process","icon":"timeline","hint":"How to organise the thinking","rows":2,"weight":1,"placeholder":"e.g. Summarise each hat, then recommend a decision and next steps..."}]},
