 "constraint": {"title":"CONSTRAIN — Constraints · Objective · Nuance · Scope · Tone · Rules · Audience · Intent · Notation","label":"CONSTRAIN","fields":[{"id":"forge_constraint_0","label":"Constraints","icon":"rule","hint":"Hard limits the output must respect","rows":2,"weight":1,"placeholder":"e.g. Maximum 120 words, no more than two sentences per paragraph..."},{"id":"forge_constraint_1","label":"Objective","icon":"target","hint":"The main task to complete","rows":4,"weight":3,"placeholder":"e.g. Write an apology email to customers about a delayed delivery...","required":true},{"id":"forge_constraint_2","label":"Nuance","icon":"tune","hint":"Subtleties to handle carefully","rows":2,"weight":1,"placeholder":"e.g. The delay was caused by a courier strike, but avoid blaming them directly..."},{"id":"forge_constraint_3","label":"Scope","icon":"filter_alt","hint":"What is in and out of scope","rows":2,"weight":1,"placeholder":"e.g. Cover the delay and new dates only, do not mention refunds..."},{"id":"forge_constraint_4","label":"Tone","icon":"record_voice_over","hint":"The tone of voice","rows":2,"weight":1,"placeholder":"e.g. Sincere, calm and reassuring..."},{"id":"forge_constraint_5","label":"Rules","icon":"format_list_bulleted","hint":"Specific rules to follow","rows":2,"weight":1,"placeholder":"e.g. Use the customer's first name, include the order number, sign off as the team..."},{"id":"forge_constraint_6","label":"Audience","icon":"groups","hint":"Who it is for","rows":2,"weight":1,"placeholder":"e.g. Online customers who ordered Christmas gifts..."},{"id":"forge_constraint_7","label":"Intent","icon":"flag","hint":"The reaction you want","rows":2,"weight":1,"placeholder":"e.g. Customers feel informed and stay loyal rather than cancelling..."},{"id":"forge_constraint_8","label":"Notation","icon":"code","hint":"Placeholders or formatting conventions","rows":2,"weight":1,"placeholder":"e.g. Use {first_name} and {order_number} as placeholders..."}]},
