 "narrative": {"title":"NARRATIVE — Need · Arc · Resolution · Relevance · Audience · Tone · Insight · Vision · Ending","label":"NARRATIVE","fields":[{"id":"forge_narrative_0","label":"Need","icon":"help","hint":"Why this story must be told","rows":2,"weight":1,"placeholder":"e.g. Staff need to understand why we are merging two offices..."},{"id":"forge_narrative_1","label":"Arc","icon":"timeline","hint":"Shape of the story","rows":4,"weight":3,"placeholder":"e.g. From early uncertainty, through the decision, to the new plan...","required":true},{"id":"forge_narrative_2","label":"Resolution","icon":"check_circle","hint":"How the story resolves","rows":2,"weight":1,"placeholder":"e.g. One combined team in Manchester by spring with no redundancies..."},{"id":"forge_narrative_3","label":"Relevance","icon":"target","hint":"Why it matters to readers","rows":2,"weight":1,"placeholder":"e.g. Explain what changes for each person's daily commute and role..."},{"id":"forge_narrative_4","label":"Audience","icon":"groups","hint":"Who will hear it","rows":2,"weight":1,"placeholder":"e.g. 120 employees across both offices, mixed seniority..."},{"id":"forge_narrative_5","label":"Tone","icon":"record_voice_over","hint":"Voice and feeling to convey","rows":2,"weight":1,"placeholder":"e.g. Honest, warm and reassuring, no corporate jargon..."},{"id":"forge_narrative_6","label":"Insight","icon":"lightbulb","hint":"Key insight to land","rows":2,"weight":1,"placeholder":"e.g. Being together will make cross-team projects far easier..."},{"id":"forge_narrative_7","label":"Vision","icon":"visibility","hint":"The future you describe","rows":2,"weight":1,"placeholder":"e.g. A shared studio space with room to grow the team..."},{"id":"forge_narrative_8","label":"Ending","icon":"flag","hint":"How to close the story","rows":2,"weight":1,"placeholder":"e.g. Close with dates for the open house and a Q&A session..."}]},
