 "tell": {"title":"TELL — Topic · Example · Lesson · Link","label":"TELL","fields":[{"id":"forge_tell_0","label":"Topic","icon":"flag","hint":"What you want to explain","rows":4,"weight":3,"placeholder":"e.g. Explain why regular backups matter for a small accounting firm...","required":true},{"id":"forge_tell_1","label":"Example","icon":"lightbulb","hint":"A story or case to use","rows":2,"weight":1,"placeholder":"e.g. A firm that lost a year of client files to ransomware..."},{"id":"forge_tell_2","label":"Lesson","icon":"school","hint":"The takeaway for the reader","rows":2,"weight":1,"placeholder":"e.g. Automatic offsite backups would have saved them in a day..."},{"id":"forge_tell_3","label":"Link","icon":"compare_arrows","hint":"How it connects to the reader","rows":2,"weight":1,"placeholder":"e.g. Relate it to the reader's own client records and deadlines..."}]},
