 "gagne": {"title":"GAGNE — Gain · Inform · Recall · Present · Guide · Elicit · Feedback · Assess · Enhance · Retain","label":"GAGNE","fields":[{"id":"forge_gagne_0","label":"Gain","icon":"campaign","hint":"Hook to gain attention","rows":2,"weight":1,"placeholder":"e.g. Open with a short video of a phishing email that cost a firm £50,000..."},{"id":"forge_gagne_1","label":"Inform","icon":"flag","hint":"Learning objectives to state","rows":2,"weight":1,"placeholder":"e.g. By the end, staff can spot five common signs of a phishing email..."},{"id":"forge_gagne_2","label":"Recall","icon":"schedule","hint":"Prior knowledge to activate","rows":2,"weight":1,"placeholder":"e.g. Ask staff to share a suspicious email they have received recently..."},{"id":"forge_gagne_3","label":"Present","icon":"description","hint":"Core content to teach","rows":4,"weight":3,"placeholder":"e.g. Build a 20 minute phishing awareness lesson covering links, senders, urgency and attachments...","required":true},{"id":"forge_gagne_4","label":"Guide","icon":"school","hint":"Support and worked examples","rows":2,"weight":1,"placeholder":"e.g. Walk through two real examples, annotating each warning sign..."},{"id":"forge_gagne_5","label":"Elicit","icon":"play_arrow","hint":"Practice activity for learners","rows":2,"weight":1,"placeholder":"e.g. Learners sort ten emails into safe and suspicious piles..."},{"id":"forge_gagne_6","label":"Feedback","icon":"chat","hint":"How to give feedback","rows":2,"weight":1,"placeholder":"e.g. Reveal answers with a short explanation for each email..."},{"id":"forge_gagne_7","label":"Assess","icon":"quiz","hint":"How to test learning","rows":2,"weight":1,"placeholder":"e.g. A five question quiz with an 80% pass mark..."},{"id":"forge_gagne_8","label":"Enhance","icon":"trending_up","hint":"How to deepen transfer","rows":2,"weight":1,"placeholder":"e.g. Ask staff to forward one real suspicious email to IT this month..."},{"id":"forge_gagne_9","label":"Retain","icon":"schedule","hint":"How to reinforce over time","rows":2,"weight":1,"placeholder":"e.g. Send a two question refresher quiz after 30 days..."}]},
